import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Search, 
  Filter, 
  Vote, 
  Clock, 
  Users, 
  Calendar,
  ArrowRight,
  CheckCircle,
  XCircle,
  TrendingUp
} from 'lucide-react';
import api from '../services/api';
import toast from 'react-hot-toast';

const Elections = () => {
  const [elections, setElections] = useState([]);
  const [filteredElections, setFilteredElections] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [filter, setFilter] = useState('all'); // all, active, ended

  useEffect(() => {
    fetchElections();
  }, []);

  useEffect(() => {
    filterElections();
  }, [elections, searchTerm, filter]);

  const fetchElections = async () => {
    try {
      const response = await api.get('/api/elections');
      setElections(response.data);
    } catch (error) {
      toast.error('Failed to load elections');
    } finally {
      setLoading(false);
    }
  };

  const filterElections = () => {
    let filtered = elections;

    // Apply search filter
    if (searchTerm) {
      filtered = filtered.filter(election =>
        election.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        election.description.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // Apply status filter
    if (filter === 'active') {
      filtered = filtered.filter(election => election.isActive);
    } else if (filter === 'ended') {
      filtered = filtered.filter(election => !election.isActive);
    }

    setFilteredElections(filtered);
  };

  const getElectionStatus = (election) => {
    const now = Math.floor(Date.now() / 1000);
    const startTime = parseInt(election.startTime);
    const endTime = parseInt(election.endTime);

    if (now < startTime) {
      return { status: 'upcoming', label: 'Upcoming', color: 'blue' };
    } else if (now >= startTime && now <= endTime && election.isActive) {
      return { status: 'active', label: 'Active', color: 'green' };
    } else {
      return { status: 'ended', label: 'Ended', color: 'gray' };
    }
  };

  const formatDate = (timestamp) => {
    return new Date(parseInt(timestamp) * 1000).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1
      }
    }
  };

  const itemVariants = {
    hidden: { y: 20, opacity: 0 },
    visible: {
      y: 0,
      opacity: 1,
      transition: {
        duration: 0.6,
        ease: "easeOut"
      }
    }
  };

  const cardVariants = {
    hidden: { scale: 0.8, opacity: 0 },
    visible: {
      scale: 1,
      opacity: 1,
      transition: {
        duration: 0.5,
        ease: "easeOut"
      }
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="w-8 h-8 border-4 border-purple-500 border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100">
      <div className="container mx-auto px-4 py-8">
        {/* Header */}
        <motion.div
          initial="hidden"
          animate="visible"
          variants={containerVariants}
          className="mb-8"
        >
          <motion.div variants={itemVariants} className="mb-6">
            <h1 className="text-3xl md:text-4xl font-bold text-gray-900 mb-2">
              Elections
            </h1>
            <p className="text-gray-600">
              Browse and participate in available elections
            </p>
          </motion.div>

          {/* Search and Filter */}
          <motion.div variants={itemVariants} className="flex flex-col md:flex-row gap-4">
            {/* Search */}
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
              <input
                type="text"
                placeholder="Search elections..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent transition-all duration-200"
              />
            </div>

            {/* Filter */}
            <div className="flex gap-2">
              <button
                onClick={() => setFilter('all')}
                className={`px-4 py-3 rounded-lg font-medium transition-all duration-200 ${
                  filter === 'all'
                    ? 'bg-purple-600 text-white'
                    : 'bg-white text-gray-700 border border-gray-300 hover:bg-gray-50'
                }`}
              >
                All
              </button>
              <button
                onClick={() => setFilter('active')}
                className={`px-4 py-3 rounded-lg font-medium transition-all duration-200 ${
                  filter === 'active'
                    ? 'bg-green-600 text-white'
                    : 'bg-white text-gray-700 border border-gray-300 hover:bg-gray-50'
                }`}
              >
                Active
              </button>
              <button
                onClick={() => setFilter('ended')}
                className={`px-4 py-3 rounded-lg font-medium transition-all duration-200 ${
                  filter === 'ended'
                    ? 'bg-gray-600 text-white'
                    : 'bg-white text-gray-700 border border-gray-300 hover:bg-gray-50'
                }`}
              >
                Ended
              </button>
            </div>
          </motion.div>
        </motion.div>

        {/* Elections Grid */}
        <motion.div
          initial="hidden"
          animate="visible"
          variants={containerVariants}
          className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6"
        >
          <AnimatePresence>
            {filteredElections.length > 0 ? (
              filteredElections.map((election, index) => {
                const status = getElectionStatus(election);
                return (
                  <motion.div
                    key={election.id}
                    variants={cardVariants}
                    whileHover={{ 
                      scale: 1.05,
                      transition: { duration: 0.2 }
                    }}
                    className="bg-white rounded-2xl shadow-lg border border-gray-100 overflow-hidden group"
                  >
                    {/* Header */}
                    <div className="p-6 border-b border-gray-100">
                      <div className="flex items-start justify-between mb-4">
                        <div className="flex-1">
                          <h3 className="text-xl font-semibold text-gray-900 mb-2 group-hover:text-purple-600 transition-colors">
                            {election.name}
                          </h3>
                          <p className="text-gray-600 text-sm line-clamp-2">
                            {election.description}
                          </p>
                        </div>
                        <div className={`ml-4 px-3 py-1 rounded-full text-xs font-medium ${
                          status.color === 'green' ? 'bg-green-100 text-green-800' :
                          status.color === 'blue' ? 'bg-blue-100 text-blue-800' :
                          'bg-gray-100 text-gray-800'
                        }`}>
                          {status.label}
                        </div>
                      </div>

                      {/* Stats */}
                      <div className="grid grid-cols-2 gap-4">
                        <div className="flex items-center space-x-2">
                          <Users className="w-4 h-4 text-gray-400" />
                          <span className="text-sm text-gray-600">
                            {election.totalVotes} votes
                          </span>
                        </div>
                        <div className="flex items-center space-x-2">
                          <Vote className="w-4 h-4 text-gray-400" />
                          <span className="text-sm text-gray-600">
                            {election.candidateCount} candidates
                          </span>
                        </div>
                      </div>
                    </div>

                    {/* Footer */}
                    <div className="p-6">
                      <div className="flex items-center justify-between mb-4">
                        <div className="flex items-center space-x-2">
                          <Calendar className="w-4 h-4 text-gray-400" />
                          <span className="text-sm text-gray-500">
                            Ends: {formatDate(election.endTime)}
                          </span>
                        </div>
                      </div>

                      <Link
                        to={`/elections/${election.id}`}
                        className="w-full flex items-center justify-center px-4 py-3 bg-gradient-to-r from-purple-600 to-pink-600 text-white font-medium rounded-lg hover:from-purple-700 hover:to-pink-700 transition-all duration-200 transform hover:scale-105 group-hover:shadow-lg"
                      >
                        {status.status === 'active' ? 'Vote Now' : 'View Details'}
                        <ArrowRight className="w-4 h-4 ml-2" />
                      </Link>
                    </div>
                  </motion.div>
                );
              })
            ) : (
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                className="col-span-full text-center py-12"
              >
                <Vote className="w-16 h-16 mx-auto mb-4 text-gray-300" />
                <h3 className="text-xl font-semibold text-gray-900 mb-2">
                  No elections found
                </h3>
                <p className="text-gray-600">
                  {searchTerm || filter !== 'all' 
                    ? 'Try adjusting your search or filter criteria'
                    : 'There are currently no elections available'
                  }
                </p>
              </motion.div>
            )}
          </AnimatePresence>
        </motion.div>

        {/* Stats Summary */}
        <motion.div
          initial="hidden"
          animate="visible"
          variants={cardVariants}
          className="mt-12 bg-white rounded-2xl shadow-lg p-6 border border-gray-100"
        >
          <h2 className="text-xl font-semibold text-gray-900 mb-6">Election Statistics</h2>
          
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
            <div className="text-center">
              <div className="text-3xl font-bold text-purple-600 mb-2">
                {elections.length}
              </div>
              <div className="text-gray-600">Total Elections</div>
            </div>
            
            <div className="text-center">
              <div className="text-3xl font-bold text-green-600 mb-2">
                {elections.filter(e => getElectionStatus(e).status === 'active').length}
              </div>
              <div className="text-gray-600">Active Elections</div>
            </div>
            
            <div className="text-center">
              <div className="text-3xl font-bold text-blue-600 mb-2">
                {elections.filter(e => getElectionStatus(e).status === 'upcoming').length}
              </div>
              <div className="text-gray-600">Upcoming Elections</div>
            </div>
            
            <div className="text-center">
              <div className="text-3xl font-bold text-gray-600 mb-2">
                {elections.reduce((sum, e) => sum + parseInt(e.totalVotes), 0)}
              </div>
              <div className="text-gray-600">Total Votes Cast</div>
            </div>
          </div>
        </motion.div>
      </div>
    </div>
  );
};

export default Elections;
